/** Seconds at each end of a run over which the operators fade in / out. */
export const OPERATOR_TRACK_FADE = 1.5;

/** The operators at walk time t: yaw / pitch (°) of boy [0] and girl [1], size, and how visible (0…1); null = not near the desk. */
export function operatorTrackAt(t: number): { yaw: [number, number]; pitch: [number, number]; size: number; show: number } | null {
  for (const run of OPERATOR_TRACK) {
    const f = (t - run.t0) / OPERATOR_TRACK_STEP;
    const n = run.rows.length;
    if (f < 0 || f > n - 1) continue;
    const i = Math.min(n - 2, Math.floor(f));
    const u = f - i;
    const a = run.rows[i];
    const b = run.rows[i + 1];
    const mix = (k: number) => a[k] + (b[k] - a[k]) * u;
    const edge = Math.min(f, n - 1 - f) * OPERATOR_TRACK_STEP;
    return { yaw: [mix(0), mix(2)], pitch: [mix(1), mix(3)], size: mix(4), show: Math.max(0, Math.min(1, edge / OPERATOR_TRACK_FADE)) };
  }
  return null;
}
